cat > /tmp/repro.mjs <<'EOF'
import axios from './index.js';
import http from 'http';

const server = http.createServer((req, res) => {
  let body = '';
  req.on('data', c => body += c);
  req.on('end', () => {
    res.end(JSON.stringify({headers: req.headers, len: Buffer.byteLength(body), body: body.slice(0, 300)}));
  });
}).listen(4445, async () => {
  const axiosInstance = axios.create({});
  const FormData = global.FormData;
  const data = new FormData();
  data.append('somePropety', 'someValue');
  try {
    const response = await axiosInstance.request({
      method: 'POST',
      url: 'http://localhost:4445',
      headers: {'Content-Type': 'multipart/form-data'},
      data,
    });
    console.log('OK', response.data.headers['content-type']);
    console.log('len ok:', response.data.len === +response.data.headers['content-length']);
    console.log(response.data.body);
  } catch (error) {
    console.error('FAIL', error.message);
  }
  server.close();
});
EOF
